package net.civeira.phylax.feature.observe.observedalert.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.valueobject.SummaryVO;

@RequiredArgsConstructor
public class SummaryValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<SummaryVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getSummary() {
    return value.map(SummaryVO::getSummary);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<SummaryVO> getSummaryValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public SummaryVO readSummary(final Optional<ObservedAlert> original,
      final ConstraintFailList fails) {
    SummaryVO result = value.orElse(original.map(ObservedAlert::getSummaryValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "summary", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param summary
   * @return
   */
  public T summary(SummaryVO summary) {
    this.value = Optional.of(summary);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param summary
   * @return
   */
  public T summary(Optional<SummaryVO> summary) {
    this.value = summary;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param summary
   * @return
   */
  public T summary(String summary) {
    this.value = Optional.of(SummaryVO.from(summary));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetSummary() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetSummaryIfMatches(final String field) {
    if ("summary".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
